    pub const CLUSTERS: usize = NEIGHBOURS + MAX_GROUPS * super::NEIGHBOURS * 2;
    pub const ALTARS: usize = CLUSTERS + MAX_CLUSTERS * 2;
    pub const OPENING: usize = ALTARS + MAX_ALTARS * 2;
    pub const ROLES: usize = OPENING + BODIES * OPENING_LEN;
    pub const FIELD_ORDER: usize = ROLES + BODIES;
