#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MatchPlan {
    /// cambc Symmetry (0 horizontal, 1 vertical, 2 rotational), NONE if unknown.
    pub symmetry: u8,
    /// hash(map, enemy picks, side): picks among equally good variants.
    pub seed: u8,
    /// Counter profile chosen from the enemy picks (0 = none).
    pub counter: u8,
    /// Round / 8 from which our roster can take a monolith safely (NONE = never).
    pub monolith_round8: u8,
    pub map_class: u8,
    pub groups: Vec<PlanGroup>,
    /// Per group: its nearest groups by walking distance (index, steps / 2), NONE-padded.
    pub neighbours: Vec<[(u8, u8); NEIGHBOURS]>,
    /// (value class, entry group) per cluster.
    pub clusters: Vec<(u8, u8)>,
    /// (safety: walk from them minus walk from us, offset by 128; walk from our spawn) per altar.
    pub altars: Vec<(u8, u8)>,
    /// First groups per body slot (champion draft order, Cassi before Issac), NONE-padded.
    pub opening: [[u8; OPENING_LEN]; BODIES],
    pub roles: [u8; BODIES],
    /// Groups whose distance fields champions compute first.
    pub field_order: Vec<u8>,
}

impl Default for MatchPlan {
    fn default() -> Self {
        Self {
            symmetry: NONE,
            seed: 0,
            counter: 0,
            monolith_round8: NONE,
            map_class: 0,
            groups: Vec::new(),
            neighbours: Vec::new(),
            clusters: Vec::new(),
            altars: Vec::new(),
            opening: [[NONE; OPENING_LEN]; BODIES],
            roles: [role::FLEX; BODIES],
            field_order: Vec::new(),
        }
    }
}

impl MatchPlan {
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.groups.is_empty()
    }

    /// Walking distance (steps / 2) between groups `a` and `b` if one lists the other as a
    /// neighbour.
    #[must_use]
    pub fn between(&self, a: usize, b: usize) -> Option<u8> {
        let find = |x: usize, y: usize| {
            self.neighbours.get(x)?.iter().find(|&&(n, _)| usize::from(n) == y).map(|&(_, d)| d)
        };
        find(a, b).or_else(|| find(b, a)).filter(|&d| d != UNKNOWN)
    }

    #[must_use]
    pub fn to_bytes(&self) -> [u8; PLAN_LEN] {
        let mut b = [0u8; PLAN_LEN];
        if self.is_empty() {
            return b;
        }
        let ng = self.groups.len().min(MAX_GROUPS);
        let h = at::HEADER;
        b[h] = VERSION;
        b[h + 1] = ng as u8;
        b[h + 2] = self.clusters.len().min(MAX_CLUSTERS) as u8;
        b[h + 3] = self.altars.len().min(MAX_ALTARS) as u8;
        b[h + 4] = self.field_order.len().min(FIELD_ORDER_LEN) as u8;
        b[h + 5] = self.symmetry;
        b[h + 6] = self.seed;
        b[h + 7] = self.counter;
        b[h + 8] = self.monolith_round8;
        b[h + 9] = self.map_class;
        for (i, g) in self.groups.iter().take(ng).enumerate() {
            let o = at::GROUPS + i * 8;
            b[o..o + 8].copy_from_slice(&[
                g.from_us, g.from_them, g.to_altar, g.altar, g.class, g.clear, g.need, g.cluster,
            ]);
        }
        for i in 0..ng {
            let row = self.neighbours.get(i).copied().unwrap_or([(NONE, UNKNOWN); NEIGHBOURS]);
            for (k, &(n, d)) in row.iter().enumerate() {
                let o = at::NEIGHBOURS + (i * NEIGHBOURS + k) * 2;
                b[o] = n;
                b[o + 1] = d;
            }
        }
        for (i, &(v, e)) in self.clusters.iter().take(MAX_CLUSTERS).enumerate() {
            b[at::CLUSTERS + i * 2] = v;
            b[at::CLUSTERS + i * 2 + 1] = e;
        }
        for (i, &(s, d)) in self.altars.iter().take(MAX_ALTARS).enumerate() {
            b[at::ALTARS + i * 2] = s;
            b[at::ALTARS + i * 2 + 1] = d;
        }
        for (s, row) in self.opening.iter().enumerate() {
            b[at::OPENING + s * OPENING_LEN..at::OPENING + (s + 1) * OPENING_LEN].copy_from_slice(row);
        }
        b[at::ROLES..at::ROLES + BODIES].copy_from_slice(&self.roles);
        for (i, &g) in self.field_order.iter().take(FIELD_ORDER_LEN).enumerate() {
            b[at::FIELD_ORDER + i] = g;
        }
        b
    }

    /// None when no plan was written (or an unknown version).
    #[must_use]
    pub fn from_bytes(b: &[u8; PLAN_LEN]) -> Option<Self> {
        let h = at::HEADER;
        if b[h] != VERSION {
            return None;
        }
        let ng = usize::from(b[h + 1]).min(MAX_GROUPS);
        let mut p = Self {
            symmetry: b[h + 5],
            seed: b[h + 6],
            counter: b[h + 7],
            monolith_round8: b[h + 8],
            map_class: b[h + 9],
            ..Self::default()
        };
        p.groups = (0..ng)
            .map(|i| {
                let o = at::GROUPS + i * 8;
                PlanGroup {
                    from_us: b[o],
                    from_them: b[o + 1],
                    to_altar: b[o + 2],
                    altar: b[o + 3],
                    class: b[o + 4],
                    clear: b[o + 5],
                    need: b[o + 6],
                    cluster: b[o + 7],
                }
            })
            .collect();
        p.neighbours = (0..ng)
            .map(|i| {
                core::array::from_fn(|k| {
                    let o = at::NEIGHBOURS + (i * NEIGHBOURS + k) * 2;
                    (b[o], b[o + 1])
                })
            })
            .collect();
        p.clusters = (0..usize::from(b[h + 2]).min(MAX_CLUSTERS))
            .map(|i| (b[at::CLUSTERS + i * 2], b[at::CLUSTERS + i * 2 + 1]))
            .collect();
        p.altars = (0..usize::from(b[h + 3]).min(MAX_ALTARS))
            .map(|i| (b[at::ALTARS + i * 2], b[at::ALTARS + i * 2 + 1]))
            .collect();
        for s in 0..BODIES {
            for k in 0..OPENING_LEN {
                p.opening[s][k] = b[at::OPENING + s * OPENING_LEN + k];
            }
        }
        p.roles.copy_from_slice(&b[at::ROLES..at::ROLES + BODIES]);
        p.field_order = b[at::FIELD_ORDER..at::FIELD_ORDER + usize::from(b[h + 4]).min(FIELD_ORDER_LEN)].to_vec();
        Some(p)
    }

    /// Scatter into draft memory (the regions in [`SEGMENTS`]).
    pub fn write(&self, mem: &mut [u8]) {
        let bytes = self.to_bytes();
        let mut at = 0;
        for (off, len) in SEGMENTS {
            mem[off..off + len].copy_from_slice(&bytes[at..at + len]);
            at += len;
        }
    }

    /// Gather from draft memory; None if no v3 plan is there.
    #[must_use]
    pub fn read(mem: &[u8]) -> Option<Self> {
        let mut bytes = [0u8; PLAN_LEN];
        let mut at = 0;
        for (off, len) in SEGMENTS {
            bytes[at..at + len].copy_from_slice(&mem[off..off + len]);
            at += len;
        }
        Self::from_bytes(&bytes)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> MatchPlan {
        let mut p = MatchPlan { symmetry: 2, seed: 77, counter: 3, monolith_round8: 90, map_class: 5, ..MatchPlan::default() };
        p.groups = (0..MAX_GROUPS as u8)
            .map(|i| PlanGroup { from_us: i, from_them: 60 - i, to_altar: 9, altar: i % 4, class: i, clear: 12, need: 2, cluster: i % 12 })
            .collect();
        p.neighbours = (0..MAX_GROUPS as u8).map(|i| [((i + 1) % 51, 3), ((i + 2) % 51, 6), (NONE, UNKNOWN)]).collect();
        p.clusters = (0..MAX_CLUSTERS as u8).map(|i| (i * 10, i)).collect();
        p.altars = vec![(140, 20), (100, 45)];
        p.opening[0] = [4, 7, NONE, NONE];
        p.roles = [role::FARMER, role::GEM_RUNNER, role::GUARD, role::FLEX, role::FLEX, role::FLEX];
        p.field_order = vec![4, 7, 1, 2];
        p
    }

    #[test]
    fn round_trips_through_draft_memory() {
        let p = sample();
        let mut mem = [0u8; 1024];
        p.write(&mut mem);
        assert_eq!(MatchPlan::read(&mem), Some(p.clone()));
        assert_eq!(p.between(3, 4), Some(3));
        assert_eq!(p.between(5, 3), Some(6), "either direction");
        assert_eq!(p.between(3, 40), None);
    }

    #[test]
    fn empty_plan_writes_nothing_and_reads_as_none() {
        let mut mem = [0u8; 1024];
        MatchPlan::default().write(&mut mem);
        assert!(mem.iter().all(|&x| x == 0));
        assert_eq!(MatchPlan::read(&mem), None);
    }

    #[test]
    fn segments_avoid_the_fields_champions_read() {
        // knobs 144..176, champion kinds 336..346, knobs2 544..576, fingerprint 576..580, CRC 1022.
        let used = [(0, 48), (144, 176), (336, 352), (544, 580), (1022, 1024)];
        for (o, l) in SEGMENTS {
            for (a, b) in used {
                assert!(o + l <= a || o >= b, "segment {o}+{l} overlaps {a}..{b}");
            }
        }
        assert_eq!(SEGMENTS.iter().map(|s| s.1).sum::<usize>(), PLAN_LEN);
    }
}
